/* ============================================================
   BACKEND (Google Apps Script Web App + Google Sheet)
   Tahap ini baru nanganin: generate nomor dokumen & simpan/lookup dokumen.
   Isi API_URL dengan URL Web App (diakhiri /exec) setelah deploy Code.gs.
   Kalau dikosongin, sistem otomatis fallback ke simulasi lokal (dummy).
   ============================================================ */
const API_URL = "https://script.google.com/macros/s/AKfycbxkR4VlHFta9teUAp7xgCVOK2OgPl2PhYYuWfUI7LbKKr2cg_TKR6o8u_Zpkg8yrcqZLA/exec";

async function apiCall(action, payload) {
  if (!API_URL) return { ok: false, error: "API_URL belum diisi" };
  try {
    const res = await fetch(API_URL, {
      method: "POST",
      // Content-Type text/plain sengaja dipakai supaya browser gak kirim
      // CORS preflight (OPTIONS) — Apps Script Web App gak bisa jawab OPTIONS.
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ action, ...payload }),
    });
    const json = await res.json();
    return json;
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

// JSONP, bukan fetch() biasa — Apps Script gak bisa ngasih header CORS di
// responsnya, jadi fetch() browser selalu gagal baca hasil walau request-nya
// sukses (lihat catatan panjang di dokumentasi backend). Lewat tag <script>,
// CORS gak berlaku sama sekali, jadi ini yang beneran tembus.
let jsonpCounter = 0;
function apiGet(action, params) {
  return new Promise((resolve) => {
    if (!API_URL) {
      resolve({ ok: false, error: "API_URL belum diisi" });
      return;
    }
    const callbackName = `__gkdJsonp${Date.now()}_${jsonpCounter++}`;
    const cleanParams = {};
    Object.entries({ action, ...params }).forEach(([k, v]) => {
      if (v !== undefined && v !== null) cleanParams[k] = v;
    });
    const qs = new URLSearchParams({ ...cleanParams, callback: callbackName }).toString();
    const script = document.createElement("script");
    let done = false;

    const cleanup = () => {
      delete window[callbackName];
      script.remove();
      clearTimeout(timeoutId);
    };

    window[callbackName] = (data) => {
      if (done) return;
      done = true;
      cleanup();
      resolve(data);
    };

    const timeoutId = setTimeout(() => {
      if (done) return;
      done = true;
      cleanup();
      resolve({ ok: false, error: "Timeout — backend gak balas dalam 15 detik." });
    }, 15000);

    script.onerror = () => {
      if (done) return;
      done = true;
      cleanup();
      resolve({ ok: false, error: "Gagal muat script JSONP (URL salah / backend gak bisa diakses)." });
    };

    script.src = `${API_URL}?${qs}`;
    document.body.appendChild(script);
  });
}

