// Judul yang ditampilkan di kop (preview & dokumen cetak) selalu didahului
// "SOP " — ini cuma buat TAMPILAN, gak ngubah data yang tersimpan. Kalau
// judulnya udah ada "SOP " di depan (misal dari backend yang udah diformat),
// gak didobel.
function judulUntukKop(judul) {
  const trimmed = String(judul || "").trim();
  if (!trimmed) return "PENGENDALIAN DOKUMEN";
  const sudahAdaSop = /^SOP\s+/i.test(trimmed);
  return (sudahAdaSop ? trimmed : `SOP ${trimmed}`).toUpperCase();
}

function bulanRomawi(bulan) {
  const r = ["I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII"];
  return r[bulan - 1];
}

function estimasiHalaman(items) {
  const textLen = Object.entries(items)
    .filter(([k]) => k !== "baganAlir" && k !== "catatanRevisi")
    .map(([, v]) => v || "")
    .join(" ").length;
  const baganPages = items.baganAlir?.pages || (items.baganAlir ? 1 : 0);
  const catatanRows = (items.catatanRevisi || []).length;
  return Math.max(1, Math.ceil(textLen / 1400) + baganPages + (catatanRows ? 1 : 0));
}

