function openFileUrl(url) {
  if (!url) return;
  const a = document.createElement("a");
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

// ID sementara buat dokumen "Baru" yang belum lolos verifikasi — nomor resmi
// (format SOP.YY/K.SS/NNN) baru diterbitkan otomatis pas lolos semua tilik.
function buatIdSementara() {
  return `Draft-${Date.now()}`;
}
function isIdSementara(nomor) {
  return typeof nomor === "string" && nomor.startsWith("Draft-");
}

function bulanNama(iso) {
  const names = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
  const m = parseInt(iso.slice(5, 7), 10);
  return names[m - 1];
}

