function TilikTierCard({ tier, doc, locked, onSubmit }) {
  const [pinOpen, setPinOpen] = useState(false);
  const [pin, setPin] = useState("");
  const [pinError, setPinError] = useState("");
  const [unlocked, setUnlocked] = useState(false);
  const [checks, setChecks] = useState([]);
  const [choice, setChoice] = useState(null);
  const [alasan, setAlasan] = useState("");

  const hasil = doc.tilik?.[tier.key] || null;
  const catatan = doc.catatanTilik?.[tier.key];

  const submitPin = () => {
    const match = PIN_MAP[pin.trim()];
    if (!match || match.key !== tier.key) {
      setPinError("PIN salah untuk tingkat ini.");
      return;
    }
    setUnlocked(true);
    setChecks(new Array(TILIK_CHECKLIST[tier.key].length).fill(false));
    setPinError("");
  };

  const toggleCheck = (idx) => {
    setChecks((arr) => arr.map((v, i) => (i === idx ? !v : v)));
  };

  const submitDecision = () => {
    if (!choice) return;
    if (choice === "revisi" && !alasan.trim()) return;
    if (choice === "selesai" && !checks.every(Boolean)) return;
    onSubmit(tier.key, choice === "selesai" ? "lolos" : "tidak", alasan.trim());
    setUnlocked(false);
    setPinOpen(false);
    setPin("");
    setChoice(null);
    setAlasan("");
  };

  const statusColor = hasil === "lolos" ? "#0F7A3D" : hasil === "tidak" ? COLOR.red : COLOR.inkMuted;
  const statusText = hasil === "lolos" ? "Selesai Ditilik" : hasil === "tidak" ? "Revisi Diminta" : "Belum Ditilik";

  return (
    <div style={styles.tilikCard}>
      <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
        <div style={{ fontSize: 12.5, fontWeight: 800 }}>{tier.label}</div>
        <span style={{ fontSize: 10.5, fontWeight: 700, color: statusColor }}>{statusText}</span>
      </div>
      {hasil === "tidak" && catatan && (
        <div style={{ fontSize: 11, color: COLOR.red, marginTop: 5, lineHeight: 1.5 }}>
          Catatan: {catatan}
        </div>
      )}

      {locked && !hasil ? (
        <div style={{ fontSize: 10.5, color: COLOR.inkMuted, marginTop: 8, lineHeight: 1.5 }}>
          Verifikasi cuma bisa dilakukan waktu status dokumen Menunggu Verifikasi.
        </div>
      ) : locked ? null : !unlocked ? (
        pinOpen ? (
          <div style={{ marginTop: 8 }}>
            <input
              type="password"
              style={{ ...styles.input, fontSize: 12.5 }}
              placeholder="PIN"
              value={pin}
              onChange={(e) => {
                setPin(e.target.value);
                setPinError("");
              }}
              onKeyDown={(e) => e.key === "Enter" && submitPin()}
            />
            {pinError && (
              <div style={{ fontSize: 10.5, color: COLOR.red, marginTop: 4 }}>{pinError}</div>
            )}
            <button
              style={{ ...styles.primaryBtn, marginTop: 6, padding: "7px 10px", fontSize: 12 }}
              onClick={submitPin}
            >
              Masuk
            </button>
          </div>
        ) : (
          <button style={styles.unlockTierBtn} onClick={() => setPinOpen(true)}>
            Masuk sebagai {tier.label}
          </button>
        )
      ) : (
        <div style={{ marginTop: 8 }}>
          <div style={{ fontSize: 10.5, fontWeight: 700, color: COLOR.inkMuted, marginBottom: 6 }}>
            Checklist ({checks.filter(Boolean).length}/{checks.length})
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
            {TILIK_CHECKLIST[tier.key].map((item, idx) => (
              <label key={idx} style={styles.checkInline} onClick={() => toggleCheck(idx)}>
                {checks[idx] ? (
                  <CheckSquare size={15} color={COLOR.primary} />
                ) : (
                  <Square size={15} color="#B7C2BF" />
                )}
                <span style={{ fontSize: 11.5, color: COLOR.ink, fontWeight: 500 }}>{item}</span>
              </label>
            ))}
          </div>

          <div style={{ display: "flex", gap: 6, marginTop: 10 }}>
            <button
              style={{
                ...styles.tilikTidakBtn,
                flex: 1,
                fontSize: 11,
                outline: choice === "revisi" ? `2px solid ${COLOR.red}` : "none",
              }}
              onClick={() => setChoice("revisi")}
            >
              Revisi
            </button>
            <button
              style={{
                ...styles.tilikLolosBtn,
                flex: 1,
                fontSize: 11,
                opacity: checks.every(Boolean) ? 1 : 0.45,
                cursor: checks.every(Boolean) ? "pointer" : "not-allowed",
                outline: choice === "selesai" ? "2px solid #0F7A3D" : "none",
              }}
              disabled={!checks.every(Boolean)}
              onClick={() => setChoice("selesai")}
            >
              Selesai
            </button>
          </div>

          {choice === "revisi" && (
            <textarea
              style={{ ...styles.input, minHeight: 50, marginTop: 8, fontSize: 11.5 }}
              placeholder="Alasan revisi..."
              value={alasan}
              onChange={(e) => setAlasan(e.target.value)}
            />
          )}

          <button
            style={{
              ...styles.primaryBtn,
              marginTop: 8,
              padding: "7px 10px",
              fontSize: 12,
              opacity: choice && (choice !== "revisi" || alasan.trim()) ? 1 : 0.45,
              cursor: choice && (choice !== "revisi" || alasan.trim()) ? "pointer" : "not-allowed",
            }}
            disabled={!choice || (choice === "revisi" && !alasan.trim())}
            onClick={submitDecision}
          >
            Kirim
          </button>
        </div>
      )}
    </div>
  );
}

